import android.app.*;import android.view.*;import android.widget.*;import com.nice.room.ui.*;import com.nice.room.ui.roomlive.tool.*;import com.hailiang.handwrite.widget.*;import com.hljzjx.classroom.mod.*;import java.util.*;
public class DiscussionPipTest{
static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}static FrameLayout.LayoutParams full(){return new FrameLayout.LayoutParams(-1,-1,0);}
static TextView named(View v,String name){if(v instanceof TextView && name.equals(((TextView)v).text))return (TextView)v;if(v instanceof ViewGroup)for(View child:((ViewGroup)v).children){TextView got=named(child,name);if(got!=null)return got;}return null;}
static class Page{RoomLiveActivity a=new RoomLiveActivity();FrameLayout host=new FrameLayout(a),root=new FrameLayout(a);HandwriteView ink=new HandwriteView(a);RoomToolBarView toolbar=new RoomToolBarView(a);TextView switcher=new TextView(a);Page(int parentId){host.id=parentId;host.clickable=true;host.focusable=true;host.attach();host.addView(root,full());ink.id=600;toolbar.id=601;switcher.id=602;switcher.width=90;switcher.left=1170;switcher.top=28;switcher.height=40;switcher.locationX=1170;switcher.locationY=28;root.addView(ink,full());root.addView(toolbar,full());root.addView(switcher,full());a.views.put(601,toolbar);a.getWindow().setDecorView(host);}}
public static void main(String[] ignored){
Page p=new Page(999);DiscussionTools.install(p.root);View.drain();ok(!p.toolbar.hideColor,"original discussion brush color options restored");
DiscussionTools.memberColor(p.ink,0xffaabbcc);ok(p.ink.color==0xffaabbcc,"initial member-assigned color remains default");DiscussionTools.chosenColor(p.ink,0xff1122ee);DiscussionTools.memberColor(p.ink,0xff00ff00);ok(p.ink.color==0xff1122ee,"member recomposition cannot replace manual color");
HandwriteView other=new HandwriteView(p.a);DiscussionTools.chosenColor(other,1);DiscussionTools.memberColor(other,2);ok(other.color==2,"color preference scoped to actual discussion canvas");
TextView back=named(p.host,"返回 PPT"),pip=named(p.host,"画中画");ok(back!=null && pip!=null,"discussion has return and PiP controls");LinearLayout controls=(LinearLayout)back.parent;FrameLayout.LayoutParams at=(FrameLayout.LayoutParams)controls.lp;
ok(at.gravity==(Gravity.TOP|Gravity.LEFT) && at.leftMargin+at.width<=1158,"upper-right controls avoid switch-group header");
Object original=p.ink.record;back.performClick();ok(p.root.visibility==View.INVISIBLE && !p.host.clickable,"PPT receives touches while discussion is minimized");ok("返回讨论".equals(back.text) && p.ink.record==original,"return preserves exact discussion drawing instance");back.performClick();ok(p.root.visibility==View.VISIBLE && p.host.clickable && p.ink.color==0xff1122ee,"discussion resumes original canvas and color");
pip.performClick();ok(p.a.enters==1 && p.a.inPip && ClassroomPip.active(p.a),"discussion button enters actual helper's PiP path");ok(controls.visibility==View.GONE && p.toolbar.visibility==View.INVISIBLE,"PiP hides both mod controls and native toolbar");
ClassroomPip.changed(p.a,false);p.a.inPip=false;ok(controls.visibility==View.VISIBLE && p.toolbar.visibility==View.VISIBLE,"PiP exit restores controls");p.host.removeView(p.root);View.drain();ok(!p.host.children.contains(controls),"ending discussion removes top controls and observers");
// Standard questions use the same upper-right placement without a group action.
Page q=new Page(200);q.switcher.visibility=View.GONE;QuestionPptReturn.install(q.root);View.drain();TextView qb=named(q.host,"返回 PPT");FrameLayout.LayoutParams qp=(FrameLayout.LayoutParams)qb.parent.lp;ok(qp.gravity==(Gravity.TOP|Gravity.LEFT) && qp.leftMargin+qp.width==1268 && qp.topMargin==16,"question return is upper-right blank space");q.host.removeView(q.root);View.drain();
for(int width:new int[]{40,1280,7000}){RoomLiveActivity a=new RoomLiveActivity();FrameLayout root=new FrameLayout(a);root.width=width;root.height=800;root.attach();a.getWindow().setDecorView(root);ClassroomPip.enter(a,root);double ratio=(double)a.lastPip.ratio.numerator/a.lastPip.ratio.denominator;ok(ratio>=.42 && ratio<=2.38,"PiP aspect ratio within system bounds");ok(a.lastPip.hint.right-a.lastPip.hint.left==width,"source hint uses actual content bounds");ClassroomPip.changed(a,false);ClassroomPip.close(a);}
for(int failure=0;failure<3;failure++){RoomLiveActivity a=new RoomLiveActivity();FrameLayout decor=new FrameLayout(a);TextView status=new TextView(a);status.id=605;decor.addView(status,full());decor.attach();a.views.put(605,status);a.getWindow().setDecorView(decor);if(failure==0)a.manager.pip=false;else if(failure==1)a.enterResult=false;else a.throwPip=true;ClassroomPip.enter(a,decor);ok(!ClassroomPip.active(a) && status.visibility==View.VISIBLE,"unsupported/denied/rejected PiP restores normal UI");ClassroomPip.close(a);}
RoomLiveActivity a=new RoomLiveActivity();FrameLayout decor=new FrameLayout(a);TextView status=new TextView(a);status.id=605;decor.addView(status,full());decor.attach();a.views.put(605,status);a.getWindow().setDecorView(decor);ClassroomPip.enter(a,decor);status.setVisibility(View.GONE);ClassroomPip.changed(a,false);ok(status.visibility==View.GONE,"PiP exit respects a newer native hidden state");ClassroomPip.close(a);ClassroomPip.enter(null);
RoomLiveActivity nativeBar=new RoomLiveActivity();RoomToolBarView bar=new RoomToolBarView(nativeBar);bar.id=300;LocalApps.registerToolbar(bar);ArrayList<FunctionToolItemInfo> items=new ArrayList<>();LocalApps.append(items,bar.state);ok(items.size()==3,"main native toolbar includes AI, Onion and PiP");LocalApps.append(items,bar.state);ok(items.size()==3,"PiP native item is not duplicated");LocalApps.close(nativeBar);
System.out.println("PASS "+checks+" discussion, upper-right placement and system-PiP Java assertions");}}
